"""Drive OpenSloper from Python through ``opensloper-cli serve``.

Each method of :class:`OpenSloper` sends one Automation API request and
returns its result. A refused call raises :class:`OpenSloperError`. Objects
are given by ID (a number) or by name. Formulas are in the pattern's unit;
positions and lengths in results are in mm.

Example::

    from opensloper import OpenSloper

    with OpenSloper() as sloper:
        sloper.add_point("freePoint", name="A", x="0", y="0")
        print(sloper.evaluate())

See https://billbsing.github.io/opensloper/reference/api/ for every method.
"""

from __future__ import annotations

import json
import os
import subprocess
from typing import Any, Literal

__all__ = ["OpenSloper", "OpenSloperError", "REFUSED", "PARSE_ERROR", "INVALID_REQUEST", "METHOD_NOT_FOUND",
           "INVALID_PARAMS", "INTERNAL_ERROR"]

# Error codes: a call understood and refused, and the JSON-RPC 2.0 errors
REFUSED = -32000
PARSE_ERROR = -32700
INVALID_REQUEST = -32600
METHOD_NOT_FOUND = -32601
INVALID_PARAMS = -32602
INTERNAL_ERROR = -32603


class OpenSloperError(Exception):
    """A refused call, or a server that stopped.

    Check ``code``, not the message, which may be translated. ``field`` and
    ``position`` say where a formula failed, when the server says so.
    """

    def __init__(self, code: int, message: str, data: Any = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.data = data

    @property
    def field(self) -> str | None:
        return self.data.get("field") if isinstance(self.data, dict) else None

    @property
    def position(self) -> int | None:
        return self.data.get("position") if isinstance(self.data, dict) else None

    def __str__(self) -> str:
        where = ""
        if self.field is not None:
            where = f" (field {self.field}"
            if self.position is not None:
                where += f", position {self.position}"
            where += ")"
        return f"{self.message}{where} [{self.code}]"


def _target(target: int | str) -> dict[str, Any]:
    """The object a method acts on, by its ID or its name."""
    if isinstance(target, int) and not isinstance(target, bool):
        return {"id": target}
    return {"name": target}


def _params(*parts: dict[str, Any]) -> dict[str, Any]:
    """The parts merged, leaving out parameters not given."""
    merged: dict[str, Any] = {}
    for part in parts:
        merged.update((key, value) for key, value in part.items() if value is not None)
    return merged


class OpenSloper:
    """A running ``opensloper-cli serve``, with one pattern open at a time.

    ``program`` is the command line program, by default ``opensloper-cli``
    on the PATH, or the OPENSLOPER_CLI environment variable when it is set.
    Use it in a ``with`` block, or call :meth:`close` when done.
    """

    def __init__(self, program: str | None = None, cwd: str | None = None):
        program = program or os.environ.get("OPENSLOPER_CLI", "opensloper-cli")
        self._next_id = 0
        self._server = subprocess.Popen([program, "serve"], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                        text=True, encoding="utf-8", cwd=cwd)

    def __enter__(self) -> OpenSloper:
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def close(self) -> None:
        """Stops the server. Changes not saved are lost."""
        if self._server.poll() is None:
            self._server.stdin.close()
            self._server.wait()

    def call(self, method: str, params: dict[str, Any] | None = None) -> Any:
        """Sends one request and returns its result, for any method by name."""
        self._next_id += 1
        request = {"jsonrpc": "2.0", "id": self._next_id, "method": method, "params": params or {}}
        try:
            self._server.stdin.write(json.dumps(request) + "\n")
            self._server.stdin.flush()
        except (BrokenPipeError, ValueError):
            raise OpenSloperError(INTERNAL_ERROR, "The server has stopped") from None
        line = self._server.stdout.readline()
        if not line:
            raise OpenSloperError(INTERNAL_ERROR, "The server has stopped")
        answer = json.loads(line)
        if "error" in answer:
            error = answer["error"]
            raise OpenSloperError(error.get("code", INTERNAL_ERROR), error.get("message", ""), error.get("data"))
        return answer.get("result")

    def _send(self, method: str, *parts: dict[str, Any]) -> Any:
        return self.call(method, _params(*parts))

    # The Automation API methods, in the order of the reference page

    def open(self, path: str, *, measurements: str | None = None, size: str | None = None) -> Any:
        """Opens a pattern, optionally with another measurement file and a size.

        Args:
            path: The pattern file (.sloper).
            measurements: A measurement file to use in place of the one the pattern names.
            size: The size to use from a size table.

        Returns:
            The pattern's file, measurement file, unit, object and variable counts, and whether it
            is modified.
        """
        return self._send("open", {
            "path": path,
            "measurements": measurements,
            "size": size,
        })

    def save(self, *, path: str | None = None) -> Any:
        """Saves the pattern.

        Args:
            path: Where to save it, a .sloper file; by default, where it was opened from. A file
                that is not a pattern is never replaced.

        Returns:
            The pattern's file, measurement file, unit, object and variable counts, and whether it
            is modified.
        """
        return self._send("save", {
            "path": path,
        })

    def convert_units(
        self,
        units: Literal["mm", "cm", "in"],
        *,
        marks: list[dict[str, Any]] | None = None,
    ) -> Any:
        """Converts the pattern to another unit, rewriting only lengths, as one undo step. While a
        number's role is open nothing changes and the reply lists it; mark each and call again.

        Args:
            units: The unit to convert to.
            marks: The numbers the formulas leave open, each marked as a length or a number.
            marks[].id: The object, by its ID or its name. Required.
            marks[].field: The field the number is in. Required.
            marks[].token: The number's token, as the reply listed it. Required.
            marks[].role: What the number is. Required.

        Returns:
            `converted` true and the new `units`; or `converted` false and the `undecided` numbers,
            each with its object, `field`, `token`, `number`, `formula` and `position` in it.
        """
        return self._send("convert_units", {
            "units": units,
            "marks": marks,
        })

    def undo(self) -> Any:
        """Undoes the last change.

        Returns:
            The pattern's file, measurement file, unit, object and variable counts, and whether it
            is modified.
        """
        return self._send("undo")

    def redo(self) -> Any:
        """Redoes the change last undone.

        Returns:
            The pattern's file, measurement file, unit, object and variable counts, and whether it
            is modified.
        """
        return self._send("redo")

    def get_measurements(self) -> Any:
        """Lists the current measurement set: its file, sizes and values in mm.

        Returns:
            `path`, `size` and `sizes` for a size table, and `measurements`, each with `key`,
            `value` and `description`.
        """
        return self._send("get_measurements")

    def set_measurement(
        self,
        key: str,
        value: float,
        *,
        size: str | None = None,
        description: str | None = None,
    ) -> Any:
        """Adds or changes one value in the measurement file, and saves the file.

        Args:
            key: The measurement's key, such as waist.
            value: The value in mm.
            size: For a size table, the size to change.
            description: Its description; by default, the one it has.

        Returns:
            `key`, `value`, whether it was `added`, and its `oldValue` when it had one.
        """
        return self._send("set_measurement", {
            "key": key,
            "value": value,
            "size": size,
            "description": description,
        })

    def missing_measurements(self) -> Any:
        """Lists what the pattern needs that the measurement set lacks.

        Returns:
            `missing`, each with its `key` and the `sizes` with no value.
        """
        return self._send("missing_measurements")

    def list_objects(self) -> Any:
        """Lists the variables and objects with their formulas, values and state.

        Returns:
            `variables` and `objects`, each as `get_object` gives it.
        """
        return self._send("list_objects")

    def get_object(self, target: int | str) -> Any:
        """Gives one object or variable: its name, ID, type, formulas (as shown), computed values
        and state.

        Args:
            target: The object, by its ID or its name.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("get_object", _target(target))

    def set_formula(self, target: int | str, field: str, formula: str) -> Any:
        """Changes one formula of an object or variable.

        Args:
            target: The object, by its ID or its name.
            field: The field, such as length or formula.
            formula: The new formula.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("set_formula", _target(target), {
            "field": field,
            "formula": formula,
        })

    def rename(self, target: int | str, newName: str) -> Any:
        """Renames an object or variable; formulas that use it follow.

        Args:
            target: The object, by its ID or its name.
            newName: The new name.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("rename", _target(target), {
            "newName": newName,
        })

    def delete(self, target: int | str) -> Any:
        """Deletes an object or variable that nothing uses.

        Args:
            target: The object, by its ID or its name.

        Returns:
            The pattern's file, measurement file, unit, object and variable counts, and whether it
            is modified.
        """
        return self._send("delete", _target(target))

    def add_variable(
        self,
        name: str,
        formula: str | float,
        *,
        description: str | None = None,
    ) -> Any:
        """Adds a variable.

        Args:
            name: Its name, used in formulas as #name.
            formula: Its formula.
            description: What it is for.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_variable", {
            "name": name,
            "formula": formula,
            "description": description,
        })

    def add_point(
        self,
        type: Literal["freePoint", "offsetPoint", "alongEdgePoint", "betweenPoint", "intersectPoint", "circleEdgePoint", "circleCirclePoint", "projectPoint"],
        *,
        name: str | None = None,
        **members: Any,
    ) -> Any:
        """Adds a point of any type.

        Args:
            type: The point's type.
            name: Its name; by default the next free one.
            **members: The type's members, as on the operations page
                (https://billbsing.github.io/opensloper/reference/operations/); points and edges are
                given by ID or name.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_point", members, {
            "type": type,
            "name": name,
        })

    def add_edge(
        self,
        type: Literal["line", "curve", "curvePath", "circle", "arc", "offsetEdge"],
        *,
        name: str | None = None,
        role: Literal["construction", "outline", "placement", "stitch", "fold", "cut", "skive", "edgeFinish"] | None = None,
        **members: Any,
    ) -> Any:
        """Adds an edge: a line, curve, curve path, circle, arc or offset edge.

        Args:
            type: The edge's type.
            name: Its name; by default the next free one.
            role: Its role; by default construction.
            **members: The type's members, as on the operations page
                (https://billbsing.github.io/opensloper/reference/operations/); points and edges are
                given by ID or name. An offset edge's `side` may also be `inside` or `outside` a
                `piece`.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_edge", members, {
            "type": type,
            "name": name,
            "role": role,
        })

    def add_repeat(
        self,
        count: str | float,
        *,
        a: int | str | None = None,
        b: int | str | None = None,
        edge: int | str | None = None,
        ends: Literal["include", "exclude"] | None = None,
        name: str | None = None,
    ) -> Any:
        """Adds a repeat: points evenly spaced between two points or along an edge.

        Args:
            a: The first point.
            b: The last point.
            edge: Along this edge, in place of a and b.
            count: How many points.
            ends: Whether the ends have points of their own.
            name: Its name; by default the next free one.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_repeat", {
            "a": a,
            "b": b,
            "edge": edge,
            "count": count,
            "ends": ends,
            "name": name,
        })

    def split_edge(self, edge: int | str, point: int | str) -> Any:
        """Splits an edge at a point on it into two parts; pieces and seams that used it take the
        parts.

        Args:
            edge: The edge.
            point: The point on it.

        Returns:
            The two parts.
        """
        return self._send("split_edge", {
            "edge": edge,
            "point": point,
        })

    def add_rectangle(
        self,
        corner: int | str,
        width: str | float,
        height: str | float,
        *,
        role: Literal["construction", "outline", "placement", "stitch", "fold", "cut", "skive", "edgeFinish"] | None = None,
    ) -> Any:
        """Adds a rectangle of four lines from a corner.

        Args:
            corner: The corner point.
            width: How far right the opposite corner is.
            height: How far down the opposite corner is.
            role: Its role; by default construction.

        Returns:
            The four lines.
        """
        return self._send("add_rectangle", {
            "corner": corner,
            "width": width,
            "height": height,
            "role": role,
        })

    def round_corner(self, edgeA: int | str, edgeB: int | str, radius: str | float) -> Any:
        """Rounds the corner where two edges meet with an arc.

        Args:
            edgeA: The first edge.
            edgeB: The second edge.
            radius: The arc's radius.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("round_corner", {
            "edgeA": edgeA,
            "edgeB": edgeB,
            "radius": radius,
        })

    def convert_edge(self, target: int | str, to: Literal["line", "curve"]) -> Any:
        """Changes an edge to a line or a curve in place, keeping its ID.

        Args:
            target: The object, by its ID or its name.
            to: What it becomes.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("convert_edge", _target(target), {
            "to": to,
        })

    def merge_points(self, points: list[int | str]) -> Any:
        """Merges two or more points into one, which every edge and formula then uses.

        Args:
            points: The points.

        Returns:
            The point kept.
        """
        return self._send("merge_points", {
            "points": points,
        })

    def break_point(self, target: int | str) -> Any:
        """Breaks a point into one for each edge that meets there.

        Args:
            target: The object, by its ID or its name.

        Returns:
            `points`, the points it became.
        """
        return self._send("break_point", _target(target))

    def copy_objects(self, objects: list[int | str]) -> Any:
        """Copies points and edges, with what they depend on, as Edit → Copy does.

        Args:
            objects: The points and edges to copy.

        Returns:
            `fragment`, the copy as text for `paste_objects`; `names`, the copied objects' names;
            `leftOut`, the names of those that cannot be copied.
        """
        return self._send("copy_objects", {
            "objects": objects,
        })

    def paste_objects(self, fragment: str) -> Any:
        """Pastes a copy as Edit → Paste does: into the pattern it came from, the objects join
        what they used there; into another, what they depend on comes too. They take new IDs, and a
        name already taken the next number.

        Args:
            fragment: The `fragment` that `copy_objects` gave.

        Returns:
            `objects`, the pasted copies of the copied objects; `renamed`, names that changed, as "A
            → A2".
        """
        return self._send("paste_objects", {
            "fragment": fragment,
        })

    def arrange(
        self,
        action: Literal["alignVertical", "alignHorizontal", "distribute", "distributeHorizontal", "distributeVertical", "distributeAlongEdge"],
        points: list[int | str],
        *,
        reference: int | str | None = None,
        edge: int | str | None = None,
        replace: list[int | str] | None = None,
    ) -> Any:
        """Aligns or distributes points. Points a formula places are left as they are and listed,
        unless named in replace.

        Args:
            action: What to do.
            points: The points.
            reference: For aligning: the point to line up with.
            edge: For distributeAlongEdge: the edge.
            replace: Points placed by a formula to change all the same.

        Returns:
            The names of the points `changed`, `asked` (left, as a formula places them) and `kept`.
        """
        return self._send("arrange", {
            "action": action,
            "points": points,
            "reference": reference,
            "edge": edge,
            "replace": replace,
        })

    def add_transform(
        self,
        type: Literal["rotate", "mirror", "move"],
        sources: list[int | str],
        *,
        name: str | None = None,
        suffix: str | None = None,
        pivot: int | str | None = None,
        angle: str | float | None = None,
        axis: dict[str, Any] | None = None,
        length: str | float | None = None,
        dx: str | float | None = None,
        dy: str | float | None = None,
        rotate: str | float | None = None,
    ) -> Any:
        """Adds rotated, mirrored or moved copies of points and edges.

        Args:
            type: The transform.
            sources: The points and edges to copy.
            name: The transform's name.
            suffix: Added to the names of the copies.
            pivot: rotate: the point to turn about; move: a point to turn the copies about.
            angle: rotate: how far to turn; mirror with axis.a only: the axis's direction; move: the
                direction.
            axis: mirror: the line to reflect in.
            axis.edge: An edge.
            axis.a: Or a point on the line.
            axis.b: And a second point on it.
            length: move: how far, at the angle.
            dx: move: how far right, in place of length.
            dy: move: how far down.
            rotate: move with pivot: how far the copies turn.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_transform", {
            "type": type,
            "sources": sources,
            "name": name,
            "suffix": suffix,
            "pivot": pivot,
            "angle": angle,
            "axis": axis,
            "length": length,
            "dx": dx,
            "dy": dy,
            "rotate": rotate,
        })

    def set_role(
        self,
        target: int | str,
        role: Literal["construction", "outline", "placement", "stitch", "fold", "cut", "skive", "edgeFinish"],
    ) -> Any:
        """Changes an edge's role. A marking role puts it on the pieces it lies in.

        Args:
            target: The object, by its ID or its name.
            role: The new role.

        Returns:
            The edge, as `get_object` gives it, with the `pieces` it is marked on.
        """
        return self._send("set_role", _target(target), {
            "role": role,
        })

    def set_marker(
        self,
        target: int | str,
        marker: Literal["plain", "hole", "button", "match"],
        *,
        size: str | float | None = None,
    ) -> Any:
        """Gives a point or repeat a marker; it is marked on the pieces it lies in.

        Args:
            target: The object, by its ID or its name.
            marker: The marker.
            size: Its size; by default a size for the marker and the pattern's unit.

        Returns:
            The edge, as `get_object` gives it, with the `pieces` it is marked on.
        """
        return self._send("set_marker", _target(target), {
            "marker": marker,
            "size": size,
        })

    def create_piece(
        self,
        x: float,
        y: float,
        *,
        name: str | None = None,
        allowance: str | float | None = None,
    ) -> Any:
        """Makes a piece from the closed outline around a place.

        Args:
            x: Across, in mm, inside the outline.
            y: Down, in mm.
            name: Its name.
            allowance: Its seam allowance; by default the first material's, or a round value for the
                pattern's unit.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("create_piece", {
            "x": x,
            "y": y,
            "name": name,
            "allowance": allowance,
        })

    def set_edge_allowance(
        self,
        target: int | str,
        edge: int | str,
        *,
        allowance: str | float | None = None,
    ) -> Any:
        """Gives one edge of a piece its own seam allowance, or clears it.

        Args:
            target: The piece, by its ID or its name.
            edge: The edge.
            allowance: The allowance; left out, the edge goes back to the piece's.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_edge_allowance", _target(target), {
            "edge": edge,
            "allowance": allowance,
        })

    def set_grainline(
        self,
        target: int | str,
        *,
        angle: str | float | None = None,
        start: int | str | None = None,
        end: int | str | None = None,
        none: bool | None = None,
    ) -> Any:
        """Sets a piece's grainline: at an angle, between two points, or none.

        Args:
            target: The piece, by its ID or its name.
            angle: At this angle.
            start: Or from this point.
            end: To this one.
            none: No grainline.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_grainline", _target(target), {
            "angle": angle,
            "start": start,
            "end": end,
            "none": none,
        })

    def add_notch(
        self,
        target: int | str,
        *,
        point: int | str | None = None,
        edge: int | str | None = None,
        position: str | float | None = None,
    ) -> Any:
        """Adds a notch on a piece's seam line, at a point or a distance along an edge.

        Args:
            target: The piece, by its ID or its name.
            point: At this point.
            edge: Or on this edge of the piece.
            position: With edge: the distance from its start.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("add_notch", _target(target), {
            "point": point,
            "edge": edge,
            "position": position,
        })

    def remove_notch(self, target: int | str, notch: int) -> Any:
        """Removes a notch.

        Args:
            target: The piece, by its ID or its name.
            notch: Its number, from 1.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("remove_notch", _target(target), {
            "notch": notch,
        })

    def add_marking(
        self,
        target: int | str,
        kind: Literal["point", "line", "stitch"],
        *,
        point: int | str | None = None,
        edge: int | str | None = None,
        spacing: str | float | None = None,
        size: str | float | None = None,
    ) -> Any:
        """Marks a point or a line on a piece, or adds stitch holes along an edge.

        Args:
            target: The piece, by its ID or its name.
            kind: What to add.
            point: point: the point or repeat.
            edge: line, stitch: the edge.
            spacing: stitch: the distance between holes.
            size: stitch: the hole size.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("add_marking", _target(target), {
            "kind": kind,
            "point": point,
            "edge": edge,
            "spacing": spacing,
            "size": size,
        })

    def remove_marking(self, target: int | str, marking: int) -> Any:
        """Removes a marking.

        Args:
            target: The piece, by its ID or its name.
            marking: Its number, from 1.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("remove_marking", _target(target), {
            "marking": marking,
        })

    def set_cut(self, target: int | str, count: int, *, mirrored: bool | None = None) -> Any:
        """Sets how many of a piece to cut, and whether every other one is mirrored.

        Args:
            target: The piece, by its ID or its name.
            count: How many.
            mirrored: Whether every other one is mirrored.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_cut", _target(target), {
            "count": count,
            "mirrored": mirrored,
        })

    def set_fold(
        self,
        target: int | str,
        *,
        edge: int | str | None = None,
        none: bool | None = None,
    ) -> Any:
        """Puts a piece on the fold of one of its straight edges, or takes it off.

        Args:
            target: The piece, by its ID or its name.
            edge: The edge.
            none: Off the fold.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_fold", _target(target), {
            "edge": edge,
            "none": none,
        })

    def set_piece_material(
        self,
        target: int | str,
        *,
        material: int | str | None = None,
        none: bool | None = None,
    ) -> Any:
        """Sets the material a piece is cut from.

        Args:
            target: The piece, by its ID or its name.
            material: The material.
            none: No material.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_piece_material", _target(target), {
            "material": material,
            "none": none,
        })

    def set_piece_fill(
        self,
        target: int | str,
        *,
        color: str | None = None,
        style: Literal["material", "tint", "hatch"] | None = None,
    ) -> Any:
        """Sets how a piece is filled on screen.

        Args:
            target: The piece, by its ID or its name.
            color: Its own colour, as #rrggbb, or empty for its material's.
            style: How it is filled.

        Returns:
            The piece, as `get_object` gives it.
        """
        return self._send("set_piece_fill", _target(target), {
            "color": color,
            "style": style,
        })

    def list_materials(self) -> Any:
        """Lists the materials and the cut list.

        Returns:
            `materials`, each with `id`, `name`, `color`, `fill` and `allowance`, and the `cutList`.
        """
        return self._send("list_materials")

    def add_material(
        self,
        *,
        name: str | None = None,
        color: str | None = None,
        fill: Literal["tint", "hatch"] | None = None,
    ) -> Any:
        """Adds a material.

        Args:
            name: Its name; by default the next free one.
            color: Its colour, as #rrggbb.
            fill: How pieces of it are filled.

        Returns:
            The materials and the cut list, as `list_materials` gives them.
        """
        return self._send("add_material", {
            "name": name,
            "color": color,
            "fill": fill,
        })

    def rename_material(self, material: int | str, name: str) -> Any:
        """Renames a material.

        Args:
            material: The material, by ID or name.
            name: The new name.

        Returns:
            The materials and the cut list, as `list_materials` gives them.
        """
        return self._send("rename_material", {
            "material": material,
            "name": name,
        })

    def set_material(
        self,
        material: int | str,
        *,
        color: str | None = None,
        fill: Literal["tint", "hatch"] | None = None,
        allowance: float | None = None,
        noAllowance: bool | None = None,
    ) -> Any:
        """Changes a material's colour, fill or seam allowance.

        Args:
            material: The material, by ID or name.
            color: Its colour, as #rrggbb.
            fill: How pieces of it are filled.
            allowance: A seam allowance for pieces of it, in the pattern's unit.
            noAllowance: Takes its seam allowance away.

        Returns:
            The materials and the cut list, as `list_materials` gives them.
        """
        return self._send("set_material", {
            "material": material,
            "color": color,
            "fill": fill,
            "allowance": allowance,
            "noAllowance": noAllowance,
        })

    def delete_material(self, material: int | str) -> Any:
        """Deletes a material; its pieces are left with none.

        Args:
            material: The material, by ID or name.

        Returns:
            The materials and the cut list, as `list_materials` gives them.
        """
        return self._send("delete_material", {
            "material": material,
        })

    def add_seam(
        self,
        sideA: list[dict[str, Any]],
        sideB: list[dict[str, Any]],
        *,
        name: str | None = None,
        ease: str | float | None = None,
        tolerance: str | float | None = None,
    ) -> Any:
        """Adds a seam: two runs of piece edges sewn together, whose lengths are checked.

        Args:
            sideA: Side A, in order along the seam.
            sideA[].piece: The piece. Required.
            sideA[].edge: The edge of that piece. Required.
            sideB: Side B.
            sideB[].piece: The piece. Required.
            sideB[].edge: The edge of that piece. Required.
            name: Its name.
            ease: How much longer side B should be; by default 0.
            tolerance: How far the difference may be from the ease; by default a small value for the
                pattern's unit.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_seam", {
            "sideA": sideA,
            "sideB": sideB,
            "name": name,
            "ease": ease,
            "tolerance": tolerance,
        })

    def flip_seam(self, target: int | str) -> Any:
        """Turns a seam's side B round, for edges sewn running the same way.

        Args:
            target: The object, by its ID or its name.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("flip_seam", _target(target))

    def suggest_seams(self) -> Any:
        """Suggests pairs of piece edges that look like they are sewn together, without adding them.

        Returns:
            `suggestions`, each with `sideA`, `sideB`, whether the edge is `shared`, and the length
            `difference`.
        """
        return self._send("suggest_seams")

    def add_note(
        self,
        text: str,
        *,
        anchor: dict[str, Any] | None = None,
        x: str | float | None = None,
        y: str | float | None = None,
        dx: str | float | None = None,
        dy: str | float | None = None,
        size: float | None = None,
        print: bool | None = None,
        leader: Literal["none", "arrow", "dot", "line"] | None = None,
        align: Literal["left", "centre", "right"] | None = None,
        box: bool | None = None,
        font: str | None = None,
        bold: bool | None = None,
        italic: bool | None = None,
        name: str | None = None,
    ) -> Any:
        """Adds a note, free or hung from a point, edge or piece; with a leader it is a callout.

        Args:
            text: The text, with draft values such as {=@waist / 4}.
            anchor: What it hangs from; left out for a free note.
            anchor.point: A point.
            anchor.edge: Or an edge.
            anchor.piece: Or a piece.
            anchor.position: With edge: how far along it, 0 to 1.
            x: A free note: its place across.
            y: A free note: its place down.
            dx: A hung note: how far right of what it hangs from.
            dy: A hung note: how far down.
            size: The text size in points.
            print: Whether it prints; by default true.
            leader: A line to what it hangs from.
            align: How its lines line up.
            box: A white box behind it.
            font: The font family it prints in; empty for the default sans-serif. One not installed
                prints in the default font.
            bold: Bold.
            italic: Italic.
            name: Its name.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("add_note", {
            "text": text,
            "anchor": anchor,
            "x": x,
            "y": y,
            "dx": dx,
            "dy": dy,
            "size": size,
            "print": print,
            "leader": leader,
            "align": align,
            "box": box,
            "font": font,
            "bold": bold,
            "italic": italic,
            "name": name,
        })

    def set_text(
        self,
        target: int | str,
        *,
        text: str | None = None,
        size: float | None = None,
        print: bool | None = None,
        leader: Literal["none", "arrow", "dot", "line"] | None = None,
        align: Literal["left", "centre", "right"] | None = None,
        box: bool | None = None,
        font: str | None = None,
        bold: bool | None = None,
        italic: bool | None = None,
    ) -> Any:
        """Changes a note's text, size, printing, leader, alignment, box or font.

        Args:
            target: The object, by its ID or its name.
            text: The text, with draft values such as {=@waist / 4}.
            size: The text size in points.
            print: Whether it prints; by default true.
            leader: A line to what it hangs from.
            align: How its lines line up.
            box: A white box behind it.
            font: The font family it prints in; empty for the default sans-serif. One not installed
                prints in the default font.
            bold: Bold.
            italic: Italic.

        Returns:
            The object, as `get_object` gives it.
        """
        return self._send("set_text", _target(target), {
            "text": text,
            "size": size,
            "print": print,
            "leader": leader,
            "align": align,
            "box": box,
            "font": font,
            "bold": bold,
            "italic": italic,
        })

    def evaluate(self) -> Any:
        """Works the pattern out again and lists its problems.

        Returns:
            The problems: objects that are invalid or blocked, gaps, and seams out of tolerance.
        """
        return self._send("evaluate")

    def check(self) -> Any:
        """As evaluate, with the full report of every computed value.

        Returns:
            The problems, and every object's computed values.
        """
        return self._send("check")

    def render(
        self,
        *,
        format: Literal["svg", "png"] | None = None,
        width: int | None = None,
        labels: bool | None = None,
        hiddenRoles: list[Literal["construction", "outline", "placement", "stitch", "fold", "cut", "skive", "edgeFinish"]] | None = None,
        annotations: bool | None = None,
        region: dict[str, Any] | None = None,
        garment: bool | None = None,
        material: str | None = None,
    ) -> Any:
        """Draws the pattern as SVG or as a PNG image, as the drafting window shows it.

        Args:
            format: svg, or png for an image; by default svg.
            width: png: the image's width in pixels, from 16 to 4096; by default 1600. Its height
                follows the drawing.
            labels: Name the points and pieces.
            hiddenRoles: Roles of edges to leave out.
            annotations: Whether to draw notes; by default true.
            region: Only this part, in mm.
            region.minX: The left or top. Required.
            region.minY: The left or top. Required.
            region.maxX: The right or bottom. Required.
            region.maxY: The right or bottom. Required.
            garment: The Garment view instead: each piece as sewn, darts closed and folds opened,
                shaded, arranged as on the canvas; labels, hiddenRoles, annotations and region do
                not apply. By default false.
            material: garment: only the pieces cut from this material, by name; by default all.

        Returns:
            `format` and the `svg` text; or, for png, the `png` file as base64 and its `width`.
        """
        return self._send("render", {
            "format": format,
            "width": width,
            "labels": labels,
            "hiddenRoles": hiddenRoles,
            "annotations": annotations,
            "region": region,
            "garment": garment,
            "material": material,
        })

    def ui_state(self) -> Any:
        """Gives the design window's state: its pattern file, the selection, the label mode and the
        part of the draft in view. Only through opensloper-cli serve --connect, with the window in
        automation mode.

        Returns:
            `file`, `modified`, `units`, `selection` (each with `id`, `name` and `type`), `labels`
            and `view`, the region in view in mm (`minX`, `minY`, `maxX`, `maxY`), which `render`
            takes as its `region`.
        """
        return self._send("ui_state")

    def export(
        self,
        layout: str,
        path: str,
        *,
        format: Literal["pdf", "svg", "dxf", "machine-dxf"] | None = None,
        profile: str | None = None,
    ) -> Any:
        """Exports a saved layout file as PDF, SVG, DXF or machine DXF.

        Args:
            layout: The layout file (.slayout).
            path: The file to write, ending in the format's extension (.pdf, .svg or .dxf).
            format: By default, from the file name's extension.
            profile: A machine profile from the settings, in place of the layout's.

        Returns:
            The `path` written.
        """
        return self._send("export", {
            "layout": layout,
            "path": path,
            "format": format,
            "profile": profile,
        })
